INSERT INTO compact_detection_guard SELECT IF(COALESCE((DATABASE() IS NOT NULL AND BINARY DATABASE()<>BINARY '__SOURCE_SCHEMA__' AND @@FOREIGN_KEY_CHECKS=1 AND @@SESSION.sql_mode REGEXP '(^|,)(STRICT_TRANS_TABLES|STRICT_ALL_TABLES)(,|$)'),FALSE),1,0);
INSERT INTO compact_detection_guard SELECT IF(COALESCE((@compact_source_quiesced=1 AND @@SESSION.transaction_isolation='REPEATABLE-READ'),FALSE),1,0);
INSERT INTO compact_detection_guard SELECT IF(COALESCE((REGEXP_LIKE('__SOURCE_DETECTION_OFFSET__','^[+-][0-9]{2}:[0-9]{2}$','c') AND CONVERT_TZ('2026-01-01','__SOURCE_DETECTION_OFFSET__','+00:00') IS NOT NULL),FALSE),1,0);
