INSERT INTO compact_detection_guard SELECT IF(COALESCE((NOT EXISTS(SELECT 1 FROM `__SOURCE_SCHEMA__`.`detection_creation_job` s LEFT JOIN workflow_instance t ON t.legacy_source='detection_creation_job' AND BINARY t.legacy_key=BINARY CAST(s.`id` AS CHAR) WHERE t.id IS NULL OR NOT((BINARY CAST(t.legacy_key AS DECIMAL(20,0))<=>BINARY s.`id`) AND (BINARY SUBSTRING(t.workflow_id,12)<=>BINARY s.`command_id`) AND (BINARY t.owner_user_id<=>BINARY s.`actor_user_id`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.actorUsername'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.actorUsername')) END<=>BINARY s.`actor_username`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.actorRole'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.actorRole')) END<=>BINARY s.`actor_role`) AND (BINARY t.request_id<=>BINARY s.`request_id`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.proposalId'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.proposalId')) END<=>BINARY s.`proposal_id`) AND (BINARY t.resource_id<=>BINARY s.`task_id`) AND (BINARY t.run_id<=>BINARY s.`dispatch_id`) AND (BINARY t.session_id<=>BINARY s.`session_id`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.previewJson'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.previewJson')) END<=>BINARY s.`preview_json`) AND (BINARY t.request_sha256<=>BINARY s.`preview_sha256`) AND (BINARY t.status<=>BINARY s.`status`) AND (BINARY t.claim_token<=>BINARY s.`owner_token`) AND (t.lease_expires_at<=>CONVERT_TZ(s.`lease_until`,'__SOURCE_DETECTION_OFFSET__','+00:00')) AND (BINARY t.error_code<=>BINARY s.`reason_code`) AND (t.created_at<=>CONVERT_TZ(s.`created_at`,'__SOURCE_DETECTION_OFFSET__','+00:00')) AND (t.updated_at<=>CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00')) AND (BINARY t.revision<=>BINARY s.`revision`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.bucketName'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.bucketName')) END<=>BINARY s.`bucket_name`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.sourcePrefix'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.sourcePrefix')) END<=>BINARY s.`source_prefix`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.manifestSha256'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.manifestSha256')) END<=>BINARY s.`manifest_sha256`)))),FALSE),1,0);
