INSERT INTO compact_detection_guard SELECT IF(COALESCE((NOT EXISTS(SELECT 1 FROM `__SOURCE_SCHEMA__`.`detection_creation_object` s LEFT JOIN workflow_instance t ON t.legacy_source='detection_creation_object' AND BINARY t.legacy_key=BINARY CAST(s.`id` AS CHAR) WHERE t.id IS NULL OR NOT((BINARY CAST(t.legacy_key AS DECIMAL(20,0))<=>BINARY s.`id`) AND (BINARY t.resource_id<=>BINARY s.`command_id`) AND (BINARY t.resource_revision<=>BINARY s.`image_index`) AND (BINARY t.run_id<=>BINARY s.`file_id`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.objectKey'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.objectKey')) END<=>BINARY s.`object_key`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.contentSha256'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.contentSha256')) END<=>BINARY s.`content_sha256`) AND (BINARY CAST(CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.byteLength'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.byteLength')) END AS DECIMAL(20,0))<=>BINARY s.`byte_length`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.contentType'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.contentType')) END<=>BINARY s.`content_type`) AND (BINARY t.status<=>BINARY s.`state`) AND (BINARY t.claim_token<=>BINARY s.`upload_token`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.etag'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.etag')) END<=>BINARY s.`etag`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.objectVersion'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.objectVersion')) END<=>BINARY s.`object_version`) AND (BINARY CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$.ossRequestId'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$.ossRequestId')) END<=>BINARY s.`oss_request_id`) AND (t.updated_at<=>CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'))))),FALSE),1,0);
