INSERT INTO compact_detection_guard SELECT IF(COALESCE((NOT EXISTS(SELECT 1 FROM compact_detection_columns e LEFT JOIN information_schema.columns a ON BINARY a.table_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY a.table_name=BINARY e.table_name AND BINARY a.column_name=BINARY e.column_name WHERE a.column_name IS NULL OR NOT(a.ordinal_position<=>e.position_no) OR NOT(BINARY LOWER(a.column_type)<=>BINARY e.column_type) OR NOT(BINARY a.is_nullable<=>BINARY e.nullable) OR NOT(BINARY a.collation_name<=>BINARY e.collation_name) OR NOT(BINARY a.character_set_name<=>BINARY IF(e.collation_name IS NULL,NULL,'utf8mb4')) OR NOT(BINARY (CASE WHEN e.extra='default_generated' THEN REPLACE(LOWER(a.column_default),'()','') ELSE a.column_default END)<=>BINARY (CASE WHEN e.extra='default_generated' THEN REPLACE(LOWER(e.default_value),'()','') ELSE e.default_value END)) OR NOT(BINARY LOWER(a.extra)<=>BINARY e.extra) OR NOT(BINARY a.generation_expression<=>BINARY ''))),FALSE),1,0);
