-- Generated by author_detection_runtime_copy.py; source artifact, NOT EXECUTED.
-- Seven original tables, 92 columns. No source writes and no guessed actor for orphan uploads.
-- Bind distinct admitted ECS schemas, actual OBJECT/REVIEW collations and evidenced fixed source UTC offset.
-- The controller must stop source writers and backups must already exist; this script does not establish quiescence.
-- Original cursors survive as legacy_key; target shared cursors are new identities.
-- Worker/upload tokens are permanent non-reclaimable execution facts; NULL completion/update times stay unknown.
-- Abort at the first SQL error, ROLLBACK on the same connection, never --force.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE compact_detection_guard(valid TINYINT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_detection_columns(table_name VARCHAR(64),column_name VARCHAR(64),position_no INT,column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_detection_source_hwm(table_name VARCHAR(64) PRIMARY KEY,next_id DECIMAL(20,0) NULL) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_detection_source_rows(table_name VARCHAR(64),key_sha256 CHAR(64),key_text LONGTEXT,row_sha256 CHAR(64),PRIMARY KEY(table_name,key_sha256)) ENGINE=InnoDB;
START TRANSACTION WITH CONSISTENT SNAPSHOT;
SELECT CONCAT('det-create:',s.command_id),CONCAT('OWNER:',s.actor_user_id),s.`request_id`,s.`preview_sha256`,s.`actor_user_id`,s.`actor_user_id`,'DETECTION_TASK',s.`task_id`,s.`dispatch_id`,s.`session_id`,s.`status`,s.`revision`,IF(s.owner_token IS NULL,0,1),s.`owner_token`,CONVERT_TZ(s.`lease_until`,'__SOURCE_DETECTION_OFFSET__','+00:00'),s.`reason_code`,JSON_OBJECT('actorUsername',s.`actor_username`,'actorRole',s.`actor_role`,'proposalId',s.`proposal_id`,'previewJson',s.`preview_json`,'bucketName',s.`bucket_name`,'sourcePrefix',s.`source_prefix`,'manifestSha256',s.`manifest_sha256`),CONVERT_TZ(s.`created_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),NULL,'DETECTION_CREATION',1,'detection_creation_job',s.`id` FROM `__SOURCE_SCHEMA__`.`detection_creation_job` s ORDER BY s.id;
SELECT CONCAT('det-upload:',LEFT(SHA2(CONCAT(s.command_id,':',s.file_id),256),48)),CONCAT('DETECTION_CREATION:',s.command_id),s.`file_id`,SHA2(CAST(JSON_OBJECT('objectKey',s.`object_key`,'contentSha256',s.`content_sha256`,'byteLength',s.`byte_length`,'contentType',s.`content_type`,'etag',NULL,'objectVersion',NULL,'ossRequestId',NULL) AS CHAR CHARACTER SET utf8mb4),256),COALESCE(j.actor_user_id,0),j.actor_user_id,'DETECTION_CREATION',s.`command_id`,s.`image_index`,s.`file_id`,s.`state`,IF(s.upload_token IS NULL,0,1),s.`upload_token`,JSON_OBJECT('objectKey',s.`object_key`,'contentSha256',s.`content_sha256`,'byteLength',s.`byte_length`,'contentType',s.`content_type`,'etag',s.`etag`,'objectVersion',s.`object_version`,'ossRequestId',s.`oss_request_id`),NULL,CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),NULL,'DETECTION_TRANSFER',1,'detection_creation_object',s.`id` FROM `__SOURCE_SCHEMA__`.`detection_creation_object` s LEFT JOIN `__SOURCE_SCHEMA__`.`detection_creation_job` j ON j.command_id=s.command_id ORDER BY s.id;
SELECT CONCAT('det-check:',s.check_id),CONCAT('OWNER:',s.actor_user_id),s.`request_id`,SHA2(CAST(JSON_OBJECT('command',s.command_id,'revision',s.expected_revision,'action',s.action,'sourceCheckId',s.source_check_id) AS CHAR CHARACTER SET utf8mb4),256),s.`actor_user_id`,s.`actor_user_id`,'DETECTION_CREATION',s.`command_id`,s.`expected_revision`,s.`status`,IF(s.worker_token IS NULL,0,1),s.`worker_token`,CONVERT_TZ(s.`lease_until`,'__SOURCE_DETECTION_OFFSET__','+00:00'),JSON_OBJECT('action',s.`action`,'sourceCheckId',s.`source_check_id`,'checkedCount',s.`checked_count`,'verifiedCount',s.`verified_count`,'evidenceJson',s.`evidence_json`,'evidenceSha256',s.`evidence_sha256`,'completedRevision',s.`completed_revision`),s.`reason_code`,CONVERT_TZ(s.`created_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),NULL,'DETECTION_TRANSFER_REVIEW',1,'detection_creation_review',s.`id` FROM `__SOURCE_SCHEMA__`.`detection_creation_review` s ORDER BY s.id;
SELECT CONCAT('det-cmd:',LEFT(SHA2(s.command_id,256),48)),CONCAT('OWNER:',s.actor_user_id),s.`request_id`,s.`payload_sha256`,s.`actor_user_id`,s.`actor_user_id`,'DETECTION_TASK',s.`task_id`,s.`dispatch_id`,'COMPLETED',JSON_OBJECT('commandId',s.`command_id`,'operation',s.`command_type`,'proposalId',s.`proposal_id`),1,CAST(s.result_json AS CHAR CHARACTER SET utf8mb4),SHA2(CAST(s.result_json AS CHAR CHARACTER SET utf8mb4),256),CONVERT_TZ(s.`created_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),NULL,NULL,'DETECTION_COMMAND',1,'detection_execution_command',s.`command_id` FROM `__SOURCE_SCHEMA__`.`detection_execution_command` s;
SELECT CONCAT('det-out:',LEFT(SHA2(s.event_id,256),48)),'DETECTION_DISPATCH',s.`event_id`,s.`payload_sha256`,s.`actor_user_id`,s.`actor_user_id`,'DETECTION_TASK',s.`task_id`,s.`dispatch_id`,s.`status`,s.`attempts`,IF(s.lease_token IS NULL,0,GREATEST(1,s.attempts)),s.`lease_token`,CONVERT_TZ(s.`lease_until`,'__SOURCE_DETECTION_OFFSET__','+00:00'),CONVERT_TZ(s.`next_attempt_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),s.`last_error_code`,JSON_OBJECT('eventJson',s.`payload_json`,'actorRequestId',s.`request_id`),CONVERT_TZ(s.`created_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),NULL,'DETECTION_DISPATCH',1,'detection_dispatch_outbox',s.`id` FROM `__SOURCE_SCHEMA__`.`detection_dispatch_outbox` s ORDER BY s.id;
SELECT CONCAT('det-worker:',LEFT(SHA2(CONCAT('[',JSON_QUOTE(s.task_id),',',JSON_QUOTE(s.dispatch_id),']'),256),48)),'DETECTION_WORKER',s.`event_id`,s.`payload_sha256`,0,NULL,'DETECTION_TASK',s.`task_id`,s.`dispatch_id`,s.`status`,1,s.`owner_id`,JSON_OBJECT('schemaVersion',1),IF(s.result_json IS NULL,NULL,1),s.`result_json`,s.`result_sha256`,CONVERT_TZ(s.`started_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),CONVERT_TZ(s.`updated_at`,'__SOURCE_DETECTION_OFFSET__','+00:00'),NULL,'DETECTION_WORKER',1,'detection_worker_receipt',CONCAT(s.task_id,CHAR(31),s.dispatch_id) FROM `__SOURCE_SCHEMA__`.`detection_worker_receipt` s;
